'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Domain score over six quarters against the healthy band (80 to 100) and the watch line (60), with every quarter labelled and the latest score and band at the end of the line.",
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "params": [
    {
      "name": "evergreen",
      "expr": "pbiColor(0)"
    },
    {
      "name": "emerald",
      "expr": "pbiColor(1)"
    },
    {
      "name": "sage",
      "value": "#DCE8E0"
    },
    {
      "name": "amber",
      "expr": "pbiColor(3)"
    },
    {
      "name": "red",
      "expr": "pbiColor(4)"
    },
    {
      "name": "ink",
      "expr": "pbiColor(0)"
    },
    {
      "name": "muted",
      "expr": "pbiColor(6)"
    },
    {
      "name": "line",
      "expr": "pbiColor(8)"
    },
    {
      "name": "surface",
      "value": "#FFFFFF"
    },
    {
      "name": "cream",
      "value": "#F7F6F2"
    },
    {
      "name": "goodFill",
      "value": "#DDF0E8"
    },
    {
      "name": "warnFill",
      "value": "#F5EAD6"
    },
    {
      "name": "badFill",
      "value": "#F3E0DA"
    },
    {
      "name": "title",
      "value": "SCORE TREND"
    },
    {
      "name": "endLabelWidth",
      "expr": "14 + 12 * 26 * 0.52 + 8"
    },
    {
      "name": "plotWidth",
      "expr": "max(60, width - endLabelWidth)"
    },
    {
      "name": "short",
      "expr": "height < 140"
    },
    {
      "name": "yFloor",
      "expr": "length(data(''dataset'')) ? min(40, floor(extent(pluck(data(''dataset''), ''Score''))[0] / 10) * 10) : 40"
    }
  ],
  "title": {
    "text": {
      "expr": "short ? '''' : title"
    },
    "subtitle": {
      "expr": "length(data(''dataset'')) && !short ? data(''dataset'')[0][''DomainName''] + '' · '' + data(''dataset'')[0][''Scope Name''] : ''''"
    },
    "font": "JetBrains Mono, Consolas, monospace",
    "fontSize": 12.5,
    "fontWeight": 600,
    "color": {
      "expr": "muted"
    },
    "anchor": "start",
    "offset": 6,
    "subtitleFont": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
    "subtitleFontSize": 12,
    "subtitleColor": {
      "expr": "muted"
    },
    "subtitlePadding": 4
  },
  "encoding": {
    "x": {
      "field": "QuarterLabel",
      "type": "ordinal",
      "sort": {
        "field": "QuarterKey",
        "op": "min"
      },
      "scale": {
        "range": [
          0,
          {
            "expr": "plotWidth"
          }
        ],
        "padding": 0.15
      },
      "axis": {
        "title": null,
        "labelAngle": 0,
        "labelExpr": "length(datum.label) > 5 ? substring(datum.label, 0, 3) + substring(datum.label, length(datum.label) - 2) : datum.label"
      }
    },
    "y": {
      "type": "quantitative",
      "scale": {
        "domain": [
          {
            "expr": "yFloor"
          },
          100
        ],
        "nice": false,
        "zero": false,
        "clamp": true
      },
      "axis": {
        "title": {
          "expr": "''Domain score, '' + yFloor + '' to 100''"
        },
        "titlePadding": 10,
        "values": {
          "expr": "yFloor < 40 ? [yFloor, 60, 80, 100] : [40, 60, 80, 100]"
        }
      }
    }
  },
  "layer": [
    {
      "data": {
        "values": [
          {
            "from": 80,
            "to": 100
          }
        ]
      },
      "mark": {
        "type": "rect",
        "color": {
          "expr": "sage"
        },
        "opacity": 0.6,
        "x": 0,
        "x2": {
          "expr": "width"
        }
      },
      "encoding": {
        "x": null,
        "y": {
          "field": "from",
          "type": "quantitative"
        },
        "y2": {
          "field": "to"
        }
      }
    },
    {
      "data": {
        "values": [
          {
            "at": 100,
            "label": "HEALTHY"
          }
        ]
      },
      "transform": [
        {
          "filter": "!short"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "top",
        "x": 8,
        "dy": 6,
        "font": "JetBrains Mono, Consolas, monospace",
        "fontSize": 12.5,
        "fontWeight": 600,
        "color": {
          "expr": "emerald"
        }
      },
      "encoding": {
        "x": null,
        "y": {
          "field": "at",
          "type": "quantitative"
        },
        "text": {
          "field": "label"
        }
      }
    },
    {
      "data": {
        "values": [
          {
            "at": 60
          }
        ]
      },
      "mark": {
        "type": "rule",
        "color": {
          "expr": "amber"
        },
        "strokeDash": [
          6,
          4
        ],
        "strokeWidth": 1.5,
        "x": 0,
        "x2": {
          "expr": "width"
        }
      },
      "encoding": {
        "x": null,
        "y": {
          "field": "at",
          "type": "quantitative"
        }
      }
    },
    {
      "data": {
        "values": [
          {
            "at": 60,
            "label": "WATCH"
          }
        ]
      },
      "transform": [
        {
          "filter": "!short"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "bottom",
        "x": 8,
        "dy": -4,
        "font": "JetBrains Mono, Consolas, monospace",
        "fontSize": 12.5,
        "fontWeight": 600,
        "color": {
          "expr": "amber"
        }
      },
      "encoding": {
        "x": null,
        "y": {
          "field": "at",
          "type": "quantitative"
        },
        "text": {
          "field": "label"
        }
      }
    },
    {
      "mark": {
        "type": "area",
        "fill": {
          "expr": "{gradient: ''linear'', x1: 0, y1: 0, x2: 0, y2: 1, stops: [{offset: 0, color: ''rgba('' + rgb(emerald).r + '','' + rgb(emerald).g + '','' + rgb(emerald).b + '',0.25)''}, {offset: 1, color: ''rgba('' + rgb(emerald).r + '','' + rgb(emerald).g + '','' + rgb(emerald).b + '',0)''}]}"
        }
      },
      "encoding": {
        "y": {
          "field": "Score"
        },
        "y2": {
          "datum": {
            "expr": "yFloor"
          }
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "color": {
          "expr": "evergreen"
        },
        "strokeWidth": 2.5
      },
      "encoding": {
        "y": {
          "field": "Score"
        }
      }
    },
    {
      "mark": {
        "type": "point",
        "filled": true,
        "size": 70,
        "opacity": 1,
        "color": {
          "expr": "emerald"
        },
        "stroke": {
          "expr": "surface"
        },
        "strokeWidth": 1.5
      },
      "encoding": {
        "y": {
          "field": "Score"
        },
        "tooltip": [
          {
            "field": "QuarterLabel",
            "title": "Quarter"
          },
          {
            "field": "Score",
            "title": "Score"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "center",
        "baseline": "bottom",
        "dy": -9,
        "font": "JetBrains Mono, Consolas, monospace",
        "fontSize": 11.5,
        "fontWeight": 600,
        "color": {
          "expr": "ink"
        }
      },
      "encoding": {
        "y": {
          "field": "Score"
        },
        "text": {
          "field": "Score"
        }
      }
    },
    {
      "transform": [
        {
          "joinaggregate": [
            {
              "op": "max",
              "field": "QuarterKey",
              "as": "lastQuarter"
            }
          ]
        },
        {
          "filter": "datum[''QuarterKey''] === datum.lastQuarter"
        },
        {
          "calculate": "datum[''Score''] + '' · '' + (datum[''Score''] >= 80 ? ''Healthy'' : datum[''Score''] >= 60 ? ''Watch'' : ''Act'')",
          "as": "lastLabel"
        }
      ],
      "layer": [
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "middle",
            "dx": 14,
            "font": "Fraunces, Cambria, Georgia, serif",
            "fontSize": 26,
            "fontWeight": 600,
            "color": {
              "expr": "surface"
            },
            "stroke": {
              "expr": "surface"
            },
            "strokeWidth": 6,
            "strokeJoin": "round"
          },
          "encoding": {
            "y": {
              "field": "Score"
            },
            "text": {
              "field": "lastLabel"
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "middle",
            "dx": 14,
            "font": "Fraunces, Cambria, Georgia, serif",
            "fontSize": 26,
            "fontWeight": 600,
            "color": {
              "expr": "ink"
            }
          },
          "encoding": {
            "y": {
              "field": "Score"
            },
            "text": {
              "field": "lastLabel"
            }
          }
        }
      ]
    },
    {
      "data": {
        "values": [
          {
            "legend": "Healthy 80 and above · Watch 60 to 79"
          }
        ]
      },
      "transform": [
        {
          "calculate": "(short && length(data(''dataset'')) ? data(''dataset'')[0].domain + '', '' + data(''dataset'')[0].scope + '' · '' : '''') + datum.legend",
          "as": "legendLine"
        }
      ],
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "top",
        "x": {
          "expr": "width"
        },
        "y": {
          "expr": "height + 30"
        },
        "font": "JetBrains Mono, Consolas, monospace",
        "fontSize": 11.5,
        "color": {
          "expr": "muted"
        }
      },
      "encoding": {
        "x": null,
        "y": null,
        "text": {
          "field": "legendLine"
        }
      }
    }
  ]
}'

'{
  "background": "transparent",
  "font": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
  "padding": 8,
  "view": {
    "stroke": null
  },
  "title": {
    "font": "Fraunces, Cambria, Georgia, serif",
    "fontSize": 17,
    "fontWeight": 600,
    "color": "#0F4D43",
    "anchor": "start",
    "offset": 12
  },
  "axis": {
    "domain": false,
    "ticks": false,
    "grid": true,
    "gridColor": "#E6E8E2",
    "gridWidth": 1,
    "labelColor": "#5F6E69",
    "labelFont": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
    "labelFontSize": 12,
    "labelPadding": 8,
    "titleColor": "#5F6E69",
    "titleFont": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
    "titleFontSize": 12,
    "titleFontWeight": "normal"
  },
  "axisX": {
    "grid": false
  },
  "legend": {
    "disable": true
  },
  "range": {
    "category": [
      "#0F4D43",
      "#0B8A6B",
      "#5E8C82",
      "#B9852C",
      "#B6462F",
      "#2A6A5F",
      "#5F6E69",
      "#CFDDD4",
      "#D6D9D2"
    ]
  },
  "text": {
    "font": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
    "color": "#0F4D43"
  },
  "line": {
    "color": "#0F4D43",
    "strokeWidth": 2.5,
    "strokeJoin": "round",
    "strokeCap": "round"
  },
  "point": {
    "color": "#0B8A6B",
    "filled": true
  },
  "rule": {
    "color": "#D6D9D2"
  }
}'
